 "content": "def transform(grid):
    """Turn the smallest detached component of the color with most objects to zero."""
    from collections import deque, Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = {}
    visited = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (bg, 0) or (r, c) in visited:
                continue
            q = deque([(r, c)])
            visited.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in visited and grid[yy][xx] == color:
                        visited.add((yy,xx)); q.append((yy,xx))
            components.setdefault(color, []).append(cells)
    if not components:
        return [row[:] for row in grid]
    color = max(components, key=lambda k: (len(components[k]), sum(map(len, components[k]))))
    # Pick the smallest *non-singleton* object: isolated specks are not the marker.
    candidates = [cells for cells in components[color] if len(cells) > 1]
    if not candidates:
        candidates = components[color]
    comp = min(candidates, key=len)
    out = [row[:] for row in grid]
    for r, c in comp:
        out[r][c] = 0
    return out
